  ('ict-board-all-2017-mcq-025', 'class9-ict-bn-guide', 'satt-ict-board.pdf p54', 'বাংলাদেশে দিন দিন কোন তথ্য প্রযুক্তিনির্ভর পেশার সম্ভাবনা উন্মোচিত হচ্ছে?', 'mcq', '{"ক":"মোবাইল ইঞ্জিনিয়ারিং","খ":"ডেটা কমিউনিকেশন","গ":"প্রোগ্রামিং","ঘ":"হার্ডওয়্যার ইঞ্জিনিয়ারিং"}'::jsonb, 'খ', 1, false, 'ict-board-all-2017-mcq', false, 'board-mcq', null, null, 'all', 2017, true),
  ('ict-board-all-2018-mcq-001', 'class9-ict-bn-guide', 'satt-ict-board.pdf p55', 'উক্ত কম্পিউটারে কী সমস্যা হতে পারে?', 'mcq', '{"ক":"পাওয়ার সাপ্লাই ইউনিট নষ্ট হয়েছে","খ":"সিপিইউ কু লার ফ্যানটি নষ্ট হয়েছে","গ":"র‍্যামে কোনো সমস্যা হয়েছে","ঘ":"হার্ডডিস্কে সমস্যা হয়েছে"}'::jsonb, 'ঘ', 1, false, 'ict-board-all-2018-mcq', false, 'board-mcq', null, 'রায়হানের স্কু লে মাল্টিমিডিয়া ক্লাস রুমে সবগুলি ডেস্কটপ কম্পিউটার। রায়হান একটি কম্পিউটার চালু করতে যেয়ে দেখল যে, সিস্টেমের বাতি জ্বলছে কিন্তু ডিসপ্লেতে কিছু দেখা যাচ্ছে না।', 'all', 2018, true),
  ('ict-board-all-2018-mcq-002', 'class9-ict-bn-guide', 'satt-ict-board.pdf p55', 'উক্ত কম্পিউটারের সমস্যা সমাধানের উপায় হতে পারে- i. র‍্যামের সংযোগগুলি ইরেজার দিয়ে পরিষ্কার করে পুনরায় লাগিয়ে দেয়া ii. নূতন হার্ডডিস্ক লাগিয়ে দেয়া iii. নূতন র‍্যাম লাগিয়ে দেয়া নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', 1, false, 'ict-board-all-2018-mcq', false, 'board-mcq', null, 'রায়হানের স্কু লে মাল্টিমিডিয়া ক্লাস রুমে সবগুলি ডেস্কটপ কম্পিউটার। রায়হান একটি কম্পিউটার চালু করতে যেয়ে দেখল যে, সিস্টেমের বাতি জ্বলছে কিন্তু ডিসপ্লেতে কিছু দেখা যাচ্ছে না।', 'all', 2018, true),
  ('ict-board-all-2018-mcq-003', 'class9-ict-bn-guide', 'satt-ict-board.pdf p55', 'নিচের ওয়ার্কশিটটি লক্ষ কর : f4 v I × √ fx A B C D E 1 2 salary sheet sl basic PF5% Net 3 name medical no salary Cut salary 4 1 kalam 22000 500 5 2 6 3 7 নিট প্রাপ্ত বেতনের জন্য সঠিক ক্রম কোনটি? = (C4+ D4)-E4, C4 * 5%', 'mcq', '{"ক":"= C4 * 5%, = (C4 + D4 ) - E4","খ":"= C4 x 5%, = (C4+ D4)-E4","গ":"= (C4+ D4)-E4, = C4 × 5%","ঘ":""}'::jsonb, 'খ', 1, false, 'ict-board-all-2018-mcq', false, 'board-mcq', 'উল্লম্ব অপশনের চিহ্ন-লাইনে পাঠ নেই — পাঠ-খণ্ড ক্রমানুসারে বসানো হয়েছে, যাচাই দরকার; ঘ অপশন খালি/অনুপস্থিত (ছাপায় নেই বা চিত্র আকারে)', null, 'all', 2018, true),
  ('ict-board-all-2018-mcq-004', 'class9-ict-bn-guide', 'satt-ict-board.pdf p55', 'প্রেজেন্টেশনে স্লাইড প্রদর্শনে কী বোর্ডের কোন কী চাপতে হবে?', 'mcq', '{"ক":"F3","খ":"F4","গ":"F6","ঘ":"F5"}'::jsonb, 'ঘ', 1, false, 'ict-board-all-2018-mcq', false, 'board-mcq', null, null, 'all', 2018, true),
  ('ict-board-all-2018-mcq-005', 'class9-ict-bn-guide', 'satt-ict-board.pdf p55', 'ফটোশপে Color Mode হচ্ছে- i. RGB ii. CMYK iii. Gray scale নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'ict-board-all-2018-mcq', false, 'board-mcq', null, null, 'all', 2018, true),
