  ('ict-board-all-2018-mcq-009', 'class9-ict-bn-guide', 'satt-ict-board.pdf p55', 'একটি নির্দিষ্ট ফিন্ডের উপর ভিত্তি করে একাধিক টেবিলের সাথে সম্পর্ক তৈরি করাকে কী বলে?', 'mcq', '{"ক":"রেফারেন্স","খ":"কু য়েরি","গ":"রিপোর্ট","ঘ":"রিলেশন"}'::jsonb, 'ঘ', 1, false, 'ict-board-all-2018-mcq', false, 'board-mcq', null, null, 'all', 2018, true),
