  ('ict-board-all-2018-mcq-012', 'class9-ict-bn-guide', 'satt-ict-board.pdf p56', 'কম্পিউটারের প্রথম প্রোগ্রামের ধারণা কে প্রবর্তন করেন ?', 'mcq', '{"ক":"কে চার্লস ব্যাবেজ","খ":"অ্যাডা ল্যান্ডলেস","গ":"জেমস ক্লার্ক ম্যাক্সওয়েল","ঘ":"বিল গেটস"}'::jsonb, 'খ', 1, false, 'ict-board-all-2018-mcq', false, 'board-mcq', null, null, 'all', 2018, true),
