  ('ict-board-all-2018-mcq-017', 'class9-ict-bn-guide', 'satt-ict-board.pdf p56', 'কম্পিউটারের কাজের স্বাভাবিক গতি বজায় রাখার জন্য প্রয়োজন— i. মাঝে মধ্যে অব্যবহৃত ফাইল পরিষ্কার করা ii. মাঝে মধ্যে কম্পিউটার খুলে ধুলাবালি পরিষ্কার করা iii. মাঝে মধ্যে ডিফ্রাগমেন্ট করা নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'ict-board-all-2018-mcq', false, 'board-mcq', null, null, 'all', 2018, true),
