  ('ict-board-barishal-2023-mcq-023', 'class9-ict-bn-guide', 'satt-ict-board.pdf p38', 'বিক্রয়মূল্য C3 নির্ণয়ে কোন সুত্রটি প্রযোজ্য?', 'mcq', '{"ক":"= A3 * B 3 % + A3 ''","খ":"= (A3 + B3 %) * A3","গ":"= A3 * B 3 + A3 %","ঘ":"= (A3 + B3 ) * A3 %"}'::jsonb, 'ক', 1, false, 'ict-board-barishal-2023-mcq', false, 'board-mcq', null, 'A B C 1 ক্রয়মূল্য লাভের হার বিক্রয় মূল্য 2 3 ১১০০ ৯ 4', 'barishal', 2023, true),
  ('ict-board-barishal-2023-mcq-024', 'class9-ict-bn-guide', 'satt-ict-board.pdf p38', 'কম্পিউটারের উক্ত সমস্যা দূরীকরণে প্রযোজ্য- i. নতু ন র‍্যাম স্থাপন করা ii. সমস্যা গ্রস্থ কু লিং ফ্যান বদলিয়ে ফেলা। iii. আপগ্রেড এন্টিভাইরাস দ্বারা হার্ডডিস্ক ড্রাইভ ক্লিন করা নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'গ', 1, false, 'ict-board-barishal-2023-mcq', false, 'board-mcq', null, 'ইদানিং রাফির কম্পিউটার ঘন ঘন হ্যাং করে বা রিস্টার্ট হয়ে যায়। রাফি তার বন্ধু আয়ানকে জানালে আয়ান তাকে ট্রাবলশুটিং, ক্ষতিকারক সফটওয়্যার ও প্রতিরধক সফটওয়্যার সম্পর্কে ধারণা ও পরামর্শ দিল।', 'barishal', 2023, true),
