  ('ict-board-barishal-2024-mcq-022', 'class9-ict-bn-guide', 'satt-ict-board.pdf p20', 'আব্দুর রহমান সাহেবের বাড়ি ভাড়া বের করার সূত্র কোনটি?', 'mcq', '{"ক":"= B2: C2%","খ":"=B2/C2","গ":"=B2*C2%","ঘ":"B2 * C2%"}'::jsonb, 'গ', 1, false, 'ict-board-barishal-2024-mcq', false, 'board-mcq', null, 'A B C D E F বাড়ি চিকিৎসা কল্যাণ নিউ 1 নাম বেসিক ভাড়া ভাতা তহবিল প্রাপ্য আব্দুর 2 ২,২০০০ ৪০% ১৫০০ ১০০ ? রহমান 3 4', 'barishal', 2024, true),
  ('ict-board-barishal-2024-mcq-023', 'class9-ict-bn-guide', 'satt-ict-board.pdf p20', '"?" স্থানের জন্য প্রযোজ্য সূত্র- i. =B2+C2+D2+E2 ii. =Sum (B2 : E2) iii = Product (B2 * E2)', 'mcq', '{"ক":"নিচের কোনটি সঠিক? i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ক', 1, false, 'ict-board-barishal-2024-mcq', false, 'board-mcq', null, 'A B C D E F বাড়ি চিকিৎসা কল্যাণ নিউ 1 নাম বেসিক ভাড়া ভাতা তহবিল প্রাপ্য আব্দুর 2 ২,২০০০ ৪০% ১৫০০ ১০০ ? রহমান 3 4', 'barishal', 2024, true),
  ('ict-board-barishal-2024-mcq-024', 'class9-ict-bn-guide', 'satt-ict-board.pdf p20', 'আফরিনের শেষ কাজটি করার সঠিক পদ্ধতি কোনটি?', 'mcq', '{"ক":"Animations → Background style → Entrance","খ":"Animations → Background style → Add","গ":"Effect","ঘ":"Animations → Custom Animation → Add Effect Custom Animation → Animations → Add Effect"}'::jsonb, 'গ', 1, false, 'ict-board-barishal-2024-mcq', false, 'board-mcq', 'উল্লম্ব অপশনের চিহ্ন-লাইনে পাঠ নেই — পাঠ-খণ্ড ক্রমানুসারে বসানো হয়েছে, যাচাই দরকার', 'আফরিন ১০ম শ্রেণির শিক্ষার্থী। বিদ্যালয়ের বার্ষিক পুরস্কার বিতরণী অনুষ্ঠানে প্রধান শিক্ষক মহোদয় তাকে বিদ্যালয়ের সাংস্কৃ তিক অনুষ্ঠানের একটি প্রেজেন্টশন তৈরি করতে বললেন। আফরিন তার স্লাইডে অনেকগুলি ছবি যুক্ত করে ভিন্ন ভিন্ন প্রক্রিয়ায় স্লাইড প্রদর্শন করল।', 'barishal', 2024, true),
  ('ict-board-barishal-2024-mcq-025', 'class9-ict-bn-guide', 'satt-ict-board.pdf p21', 'আফনির তার কাজটি আকর্ষণীয় করার জন্য- i. ছবিগুলো সিলেক্ট করল ii. blinds, fly in, diamond ইত্যাদি পছন্দমত ইফেক্ট ব্যবহার করল iii "Apply to all'' অপশন ব্যবহার করল নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'ঘ', 1, false, 'ict-board-barishal-2024-mcq', false, 'board-mcq', null, 'আফরিন ১০ম শ্রেণির শিক্ষার্থী। বিদ্যালয়ের বার্ষিক পুরস্কার বিতরণী অনুষ্ঠানে প্রধান শিক্ষক মহোদয় তাকে বিদ্যালয়ের সাংস্কৃ তিক অনুষ্ঠানের একটি প্রেজেন্টশন তৈরি করতে বললেন। আফরিন তার স্লাইডে অনেকগুলি ছবি যুক্ত করে ভিন্ন ভিন্ন প্রক্রিয়ায় স্লাইড প্রদর্শন করল।', 'barishal', 2024, true),
  ('ict-board-barishal-2025-mcq-001', 'class9-ict-bn-guide', 'satt-ict-board.pdf p4', 'জনপ্রিয় ই-বুক রিডার, ''Kindle'' এর স্বত্বাধিকারী কোন প্রতিষ্ঠান?', 'mcq', '{"ক":"microsoft","খ":"amazon","গ":"google","ঘ":"apple"}'::jsonb, 'খ', 1, false, 'ict-board-barishal-2025-mcq', false, 'board-mcq', null, null, 'barishal', 2025, true),
