  ('ict-board-barishal-2025-mcq-023', 'class9-ict-bn-guide', 'satt-ict-board.pdf p6', 'কোনটির সমস্যার কারণে কম্পিউটারের বায়োসের কোনো অপশন পরিবর্তন করলে সেভ হয় না?', 'mcq', '{"ক":"RAM","খ":"ROM","গ":"CMOS","ঘ":"MEMORY"}'::jsonb, 'গ', 1, false, 'ict-board-barishal-2025-mcq', false, 'board-mcq', null, null, 'barishal', 2025, true),
  ('ict-board-barishal-2025-mcq-024', 'class9-ict-bn-guide', 'satt-ict-board.pdf p6', 'জালাল কোন ধরনের শিক্ষা ব্যবস্থার সাথে সম্পৃক্ত?', 'mcq', '{"ক":"ই-লার্নিং এডু কেশন","খ":"কম্পিউটিং এডু কেশন","গ":"ব্লান্ডিং এডু কেশন","ঘ":"ডাইরেক্ট এডু কেশন"}'::jsonb, 'ক', 1, false, 'ict-board-barishal-2025-mcq', false, 'board-mcq', null, 'জালাল তার গ্রামের বাড়ি থেকে ঢাকা বিশ্ববিদ্যালয়ের একটি অনলাইন ক্লাসে যুক্ত হলো। শিক্ষক বিজ্ঞানের একটি অধ্যায় থেকে মানবদেহে রক্ত সঞ্চালন প্রক্রিয়া পড়াচ্ছিলেন। তিনি পাঠকে আকর্ষণীয় ও বোধগম্য করার জন্য বিভিন্ন ধরনের Content ব্যবহার করেন।', 'barishal', 2025, true),
  ('ict-board-barishal-2025-mcq-025', 'class9-ict-bn-guide', 'satt-ict-board.pdf p6', 'উদ্দীপকে বর্ণিত শিক্ষকের পাঠদান পদ্ধতি যে সব বিষয়ে বেশি কার্যকর i. বিজ্ঞানের এক্সপিরিমেন্টাল বিষয়সমূহ. ii. অদৃশ্য বিষয়সমূহ iii. জটিল বিষয়সমূহ নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', 1, false, 'ict-board-barishal-2025-mcq', false, 'board-mcq', null, 'জালাল তার গ্রামের বাড়ি থেকে ঢাকা বিশ্ববিদ্যালয়ের একটি অনলাইন ক্লাসে যুক্ত হলো। শিক্ষক বিজ্ঞানের একটি অধ্যায় থেকে মানবদেহে রক্ত সঞ্চালন প্রক্রিয়া পড়াচ্ছিলেন। তিনি পাঠকে আকর্ষণীয় ও বোধগম্য করার জন্য বিভিন্ন ধরনের Content ব্যবহার করেন।', 'barishal', 2025, true),
  ('ict-board-chattogram-2023-mcq-001', 'class9-ict-bn-guide', 'satt-ict-board.pdf p47', '''X'' এর Total number বের করতে কোন সূত্র ব্যবহার করতে হবে? i. = B2 + C2 + D2 ii. Sum (B2 + C2 + D2 ) iii. = Sum (B2 : D2 ) i ও ii i ও iii', 'mcq', '{"ক":"","খ":"","গ":"ii ও iii","ঘ":"i, ii ও iii"}'::jsonb, 'খ', 1, false, 'ict-board-chattogram-2023-mcq', false, 'board-mcq', 'ক অপশন খালি/অনুপস্থিত (ছাপায় নেই বা চিত্র আকারে); খ অপশন খালি/অনুপস্থিত (ছাপায় নেই বা চিত্র আকারে)', 'A B C D E F Name 1 Bang Eng Math Total Average 2 X 50 55 75 ? 3 Y 60 65 70 4 Z 55 45 50', 'chattogram', 2023, true),
  ('ict-board-chattogram-2023-mcq-002', 'class9-ict-bn-guide', 'satt-ict-board.pdf p47', '''?'' চিহ্নিত F2 সেলে কত হবে?', 'mcq', '{"ক":"60","খ":"60.65","গ":"65","ঘ":"66.33"}'::jsonb, 'ক', 1, false, 'ict-board-chattogram-2023-mcq', false, 'board-mcq', null, 'A B C D E F Name 1 Bang Eng Math Total Average 2 X 50 55 75 ? 3 Y 60 65 70 4 Z 55 45 50', 'chattogram', 2023, true),
  ('ict-board-chattogram-2023-mcq-003', 'class9-ict-bn-guide', 'satt-ict-board.pdf p47', 'দেশের দক্ষ প্রোগ্রামাররা কীসের মাধ্যমে বিশ্ববিখ্যাত ইনটেল কোম্পানির কাজ করছে?', 'mcq', '{"ক":"ই-মেইল","খ":"ফেসবুক","গ":"ফ্রিল্যান্সিং","ঘ":"মাল্টিমিডিয়া"}'::jsonb, 'গ', 1, false, 'ict-board-chattogram-2023-mcq', false, 'board-mcq', null, null, 'chattogram', 2023, true),
  ('ict-board-chattogram-2023-mcq-004', 'class9-ict-bn-guide', 'satt-ict-board.pdf p47', 'মি. X একটি ফার্মে চাকরি করেন। তিনি দৈনন্দিন হিসাব খাতার মধ্যে তু লে রাখেন। তার বন্ধু একদিন এসে তাকে বললো, বর্তমানে এসব হিসাব নিকাশের জন্য অনেক সফটওয়্যার আছে। সে সব সফওয়ারে হিসাব নিকাশের কাজ করা অনেক সহজ এবং ডকু মেন্ট সংরক্ষন ও করা যায়। উদ্দীপকে কোন ধরনের সফটওয়্যারের কথা বলা হয়েছে।', 'mcq', '{"ক":"মাইক্রোসফটওয়্যার","খ":"ওয়ার্ড প্রসেসর","গ":"পাওয়ার পয়েন্ট","ঘ":"স্প্রেডশিট এনালাইসিস"}'::jsonb, 'ঘ', 1, false, 'ict-board-chattogram-2023-mcq', false, 'board-mcq', null, null, 'chattogram', 2023, true),
  ('ict-board-chattogram-2023-mcq-005', 'class9-ict-bn-guide', 'satt-ict-board.pdf p47', 'উদ্দীপকে উল্লিখিত সফটওয়্যার ব্যবহারের মূল সুবিধা কী সংখ্যা ও উপাত্ত নিয়ে সহজে কাজ করা যায়', 'mcq', '{"ক":"নির্ভুলভাবে লেখালেখি করা যায়","খ":"লেখাকে পুনবিন্যাস করা যায়।","গ":"বানান সংশোধন করা যায়","ঘ":""}'::jsonb, 'ক', 1, false, 'ict-board-chattogram-2023-mcq', false, 'board-mcq', 'উল্লম্ব অপশনের চিহ্ন-লাইনে পাঠ নেই — পাঠ-খণ্ড ক্রমানুসারে বসানো হয়েছে, যাচাই দরকার; ঘ অপশন খালি/অনুপস্থিত (ছাপায় নেই বা চিত্র আকারে)', null, 'chattogram', 2023, true),
  ('ict-board-chattogram-2023-mcq-006', 'class9-ict-bn-guide', 'satt-ict-board.pdf p47', 'টেক্সট, গ্রাফিক্স, অডিও দিয়ে কনটেন্টস তৈরি সফটওয়্যারটির নাম কী?', 'mcq', '{"ক":"এডোবি ইলাস্টের","খ":"পিকাশাে","গ":"পাওয়ার পয়েন্ট","ঘ":"এডোবি ফটোশপ"}'::jsonb, 'ঘ', 1, false, 'ict-board-chattogram-2023-mcq', false, 'board-mcq', null, null, 'chattogram', 2023, true),
