  ('ict-board-chattogram-2023-mcq-009', 'class9-ict-bn-guide', 'satt-ict-board.pdf p48', 'সার্চ ইঞ্জিন চালানোর জন্য কোন ভাষায় দক্ষ হওয়া প্রয়োজন?', 'mcq', '{"ক":"ইংরেজি ভাষা","খ":"বাংলা ভাষা","গ":"প্রোগ্রামিং ভাষা","ঘ":"উচ্চস্তরের ভাষা"}'::jsonb, 'ক', 1, false, 'ict-board-chattogram-2023-mcq', false, 'board-mcq', null, null, 'chattogram', 2023, true),
