  ('ict-board-chattogram-2023-mcq-013', 'class9-ict-bn-guide', 'satt-ict-board.pdf p48', 'আসক্তি থেকে মুক্ত থাকার জন্য কোন কাজটি করা উচিত?', 'mcq', '{"ক":"লেখাপড়া","খ":"হোমওয়ার্ক ও খেলাধুলা","গ":"নিজেকে বোঝাতে হবে ও স্বীকার করে নিতে হবে","ঘ":"সামাজিক যোগাযোগ সহিট ব্যবহারের প্রতি অনীহা"}'::jsonb, 'গ', 1, false, 'ict-board-chattogram-2023-mcq', false, 'board-mcq', null, null, 'chattogram', 2023, true),
