  ('ict-board-chattogram-2023-mcq-019', 'class9-ict-bn-guide', 'satt-ict-board.pdf p48', 'সরকার শিক্ষার্থীদের বিশ্বমানের শিক্ষা অর্জনের জন্য কোনটির গুরুত্ব দিচ্ছে?', 'mcq', '{"ক":"ডিজিটাল লার্নিং","খ":"ই লার্নিং c ডেই- গভর্নেন্স","গ":"","ঘ":"ই- সার্ভিস"}'::jsonb, 'খ', 1, false, 'ict-board-chattogram-2023-mcq', false, 'board-mcq', 'অপশন চিহ্ন পাওয়া যায়নি: গ (ছাপায় নেই বা চিত্র আকারে); গ অপশন খালি/অনুপস্থিত (ছাপায় নেই বা চিত্র আকারে)', null, 'chattogram', 2023, true),
