  ('ict-board-cumilla-2025-mcq-001', 'class9-ict-bn-guide', 'satt-ict-board.pdf p8', 'শাফিনের কম্পিউটারের এই অবস্থার জন্য কোনটি দায়ী হতে পারে?', 'mcq', '{"ক":"সিস্টেম সফটওয়্যার","খ":"ভাইরাস সফটওয়্যার এন্টিভাইরাস","গ":"ইউটিলিটি সফটওয়্যার","ঘ":"সফটওয়‍্যার"}'::jsonb, 'খ', 1, false, 'ict-board-cumilla-2025-mcq', false, 'board-mcq', null, 'শাফিন কম্পিউটারে কাজ করার সময় দেখতে পেল, তার কম্পিউটারে সংরক্ষিত ফাইল মুছে যাচ্ছে এবং ডেটা বিকৃ ত হয়ে যাচ্ছে। তার করণীয় কাজ কী? শিক্ষকের কাছে জানতে চাইলে তিনি এর প্রতিরোধের জন্য কয়েকটি সফটওয়ারের নাম বলে দিলেন।', 'cumilla', 2025, true),
  ('ict-board-cumilla-2025-mcq-002', 'class9-ict-bn-guide', 'satt-ict-board.pdf p8', 'শাফিনের শিক্ষক কম্পিউটারের তথ্যসমূহ ক্ষতিসাধনের প্রতিরোধ হিসেবে কোন কোন সফটওয়ার এর নাম বলতে পারেন? i. এভিজি ii. এভাস্ট iii. ভিয়েনা নিচের কোনটি সঠিক?', 'mcq', '{"ক":"i ও ii","খ":"i ও iii","গ":"ii ও iii","ঘ":"i ii ও iii"}'::jsonb, 'ক', 1, false, 'ict-board-cumilla-2025-mcq', false, 'board-mcq', null, 'শাফিন কম্পিউটারে কাজ করার সময় দেখতে পেল, তার কম্পিউটারে সংরক্ষিত ফাইল মুছে যাচ্ছে এবং ডেটা বিকৃ ত হয়ে যাচ্ছে। তার করণীয় কাজ কী? শিক্ষকের কাছে জানতে চাইলে তিনি এর প্রতিরোধের জন্য কয়েকটি সফটওয়ারের নাম বলে দিলেন।', 'cumilla', 2025, true),
  ('ict-board-cumilla-2025-mcq-003', 'class9-ict-bn-guide', 'satt-ict-board.pdf p8', 'আরিয়ানা বই ডাউনলোড করার ক্ষেত্রে কোন পদ্ধতিটি বেছে নেবে?', 'mcq', '{"ক":"ডেএইচ টি এমএল","খ":"ই বুক রিডার","গ":"পিডিএফ","ঘ":"অ্যামাজান"}'::jsonb, 'গ', 1, false, 'ict-board-cumilla-2025-mcq', false, 'board-mcq', 'উল্লম্ব অপশনের চিহ্ন-লাইনে পাঠ নেই — পাঠ-খণ্ড ক্রমানুসারে বসানো হয়েছে, যাচাই দরকার', 'সম্প্রতি বন্যায় আরিয়ানার বইখাতা সব নষ্ট হয়ে গেলে তার মা উদ্বিগ্ন হওয়ায় আরিয়ানা তার মাকে বলে, সমস্যা নেই আমি ইন্টারনেট থেকে পাঠ্যবই ডাউনলোড করে নেবো এবং মাল্টিমিডিয়া সমৃদ্ধ অন্যান্য বই পড়বো।', 'cumilla', 2025, true),
